from typing import Union
from time import sleep

from taf.gnb.oam.coam.cu import cu as cu_api
from taf.gnb.oam.coam.cu.exception import AuthenticationFailed as AuthenticationFailedCu
from taf.gnb.oam.coam.vdu import vdu as du_api
from taf.gnb.oam.coam.vdu.exceptions import AuthenticationFailed as AuthenticationFailedDu

from taf.rfrl.procedures.resources.python.bts.bts.bts import Bts
from taf.rfrl.procedures.resources.python.bts.components.component_collection import ComponentCollection
from taf.rfrl.procedures.resources.python.bts.components.cu.cu import Cu
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info, log_debug
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import BtsConfig
from taf.rfrl.procedures.resources.python.bts.utils.ip import check_if_ip_is_reachable_via_https
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import UsageError


class CloudBts(Bts):
    """ Represents BTS in Cloud Radio Access Network (vRAN). """

    def __init__(self,
                 bts_init_config: BtsConfig,
                 ip: str = '192.168.100.129',
                 port: int = 443,
                 user_name: str = 'Nemuadmin',
                 password: str = 'Nokia@123',
                 password_when_uncommissioned: str = 'nemuuser'):
        """
        :param bts_init_config: configuration details, taken from init file, of this BTS;
        :param ip: IP address of this BTS to which API connection should open; defaults to '192.168.100.129'
        :param port: port number on which API connection should open; defaults to 443
        :param user_name: login used for authentication during opening API connection; defaults to 'Nemuadmin'
        :param password: password used for authentication during opening API connection; defaults to 'Nokia@123'
        :param password_when_uncommissioned: password used for authentication during opening API connection for
                                             uncommissioned CU/DU; defaults to 'nemuuser'
        """
        log_info('Creating new Cloud BTS', to_console=True)
        super(CloudBts, self).__init__(ip, port, user_name, password)
        self._bts_init_config = bts_init_config
        if not self._bts_init_config.cu.instance_id:
            raise UsageError("instance_id for CloudBts cannot be None or empty. Please check if CU object has defined "
                             "instance_id in init file.")
        self._name = f'CloudBts_{self._bts_init_config.cu.instance_id}'
        self._api_cu = cu_api()
        self._api_du = du_api()
        self._api_cu_alias = f'CloudBts{id(self)}'
        self._api_du_aliases = {}
        self._ran = 'Cloud'
        self._cus = ComponentCollection()
        self._password_when_uncommissioned = password_when_uncommissioned

    @property
    def string_representation(self):
        info = f'{self._name} (RAN: {self._ran}, node: {self.node}, mode: {self._mode}):'

        for cu in self._cus:
            info += f'\n{cu.string_representation}'

        return info

    @property
    def name(self) -> str:
        """ Returns name of this BTS. """
        return self._name

    @property
    def node(self) -> Union[str, None]:
        """ Returns type of Node B for this BTS, i.e. 'gNB'. If no Cells configured then None is returned. """
        return self._get_node()

    @property
    def mode(self) -> str:
        """ Returns mode in which BTS is operating, i.e. 'NSA'. """
        return self._mode

    @property
    def cus(self) -> ComponentCollection:
        """ Returns all CUs connected to this BTS. """
        return self._cus

    @property
    def dus(self) -> ComponentCollection:
        """ Returns all DUs connected to this BTS. """
        dus = ComponentCollection()
        [dus.extend(cu.dus) for cu in self.cus]

        unique_dus = ComponentCollection()
        [unique_dus.append(du) for du in dus if du not in unique_dus]

        return unique_dus

    @property
    def rmods(self) -> ComponentCollection:
        """ Returns all RMODs connected to this BTS. """
        rmods = ComponentCollection()
        [rmods.extend(du.rmods) for du in self.dus]

        unique_rmods = ComponentCollection()
        [unique_rmods.append(rmod) for rmod in rmods if rmod not in unique_rmods]

        return unique_rmods

    @property
    def cells(self) -> ComponentCollection:
        """ Returns all Cells configured on this BTS. """
        cells = ComponentCollection()
        [cells.extend(rmod.cells) for rmod in self.rmods]

        unique_cells = ComponentCollection()
        [unique_cells.append(cell) for cell in cells if cell not in unique_cells]

        return unique_cells

    @pretty_log
    def connect(self):
        """ Opens API connections to this BTS. """
        self._connect_to_cu()

        if self._bts_init_config.dus:
            for du_id, du_config in enumerate(self._bts_init_config.dus, start=1):
                self._connect_to_du(du_id, du_config.oam_http_connection_details)

    @pretty_log
    def load(self):
        """
        Loads all components currently connected to this BTS.
        Each time current BTS configuration changes (i.e. due to recomissioning which adds/removes BTS component)
        BTS needs to be reloaded using this method. If any component has had instance of alarms watchdog,
        it will be passed to the component during loading.
        """
        log_info(f'Loading {self._name}', to_console=True)
        cu_info = self._api_cu.get_cu_state(connection=self._api_cu_alias)
        self._mode = cu_info['type']
        dus_init_configs = self._bts_init_config.dus if self._bts_init_config.dus else []
        cu_init_config = self._bts_init_config.cu

        cu_alarms_watchdog = self._cus[0].alarms_watchdog if self._cus else None
        dus_alarms_watchdog = {du.instance_id: du.alarms_watchdog for du in self._cus[0].dus} if self._cus else {}

        cu = Cu(cu_info=cu_info,
                api_cu=self._api_cu,
                api_du=self._api_du,
                api_cu_alias=self._api_cu_alias,
                api_du_aliases=self._api_du_aliases,
                cu_init_config=cu_init_config,
                dus_init_configs=dus_init_configs,
                cu_alarms_watchdog=cu_alarms_watchdog)

        cu.load(dus_alarms_watchdog=dus_alarms_watchdog)
        self._cus = ComponentCollection([cu])
        log_info(f'Loaded {self.string_representation}')

    @pretty_log
    def is_cu_uncommissioned(self) -> bool:
        """
        Checks if CU is uncommissioned by checking its operational state. Uses only internal API.
        """
        cu_info = self._api_cu.get_cu_state(connection=self._api_cu_alias,
                                            use_m2m=False)
        return cu_info['operational_state'] is None

    @pretty_log
    def is_du_uncommissioned(self, du_id: Union[str, int]) -> bool:
        """
        Checks if DU is uncommissioned by checking its operational state. Uses only internal API.
        """
        du_info = self._api_du.get_vdu_state_data(vdu_connection=self._api_du_aliases[str(du_id)],
                                                  use_m2m=False)
        return du_info['operational_state'] is None

    @pretty_log
    def commission_cu(self, scf_path: str, timeout: int = 300, wait_for_completion: bool = True):
        """
        Performs commissioning on CU using internal API. Should be used only for uncommissioned CU.
        """
        log_info(f'Commissioning CU config from SCF file {scf_path}', to_console=True)
        self._api_cu.perform_commissioning(scf_file=scf_path,
                                           connection=self._api_cu_alias,
                                           timeout=timeout,
                                           wait_for_completion=wait_for_completion)

    @pretty_log
    def commission_du(self, scf_path: str, du_id: Union[str, int], timeout: int = 300, wait_for_completion: bool = True):
        """
        Performs commissioning on DU using internal API. Should be used only for uncommissioned DU.
        """
        log_info(f'Commissioning DU config from SCF file {scf_path}', to_console=True)
        self._api_du.perform_commissioning(scf_file=scf_path,
                                           vdu_connection=self._api_du_aliases[str(du_id)],
                                           timeout=timeout,
                                           wait_for_completion=wait_for_completion)

    @pretty_log
    def disconnect(self):
        """ Closes API connections to this BTS. """
        log_info(f'Disconnecting from Cloud BTS with IP: {self._ip}', to_console=True)
        self._api_cu.disconnect(connection=self._api_cu_alias)

        for du_id, api_du_alias in self._api_du_aliases.items():
            log_debug(f'Disconnecting from DU{du_id}')
            self._api_du.disconnect(vdu_connection=api_du_alias)

        self._api_du_aliases.clear()

    @pretty_log
    def check_if_reachable(self, delay: int = 0, timeout: int = 5):
        """
        Checks whether this BTS is reachable via HTTPS.
        :param delay: time (in seconds) to wait before checking if BTS is reachable;
                      defaults to 0 (no delay)
        :param timeout: time (in seconds) for BTS to become reachable;
                        defaults to 5
        :raises ResultError: if BTS doesn't become reachable before the timeout
        """
        timeout_msg = f" before {timeout}s timeout" if timeout else ""
        log_info(f'Checking if BTS is reachable{timeout_msg}', to_console=True)
        sleep(delay)
        check_if_ip_is_reachable_via_https(ip=self._ip, timeout=timeout)

        for du_init_config in self._bts_init_config.dus:
            check_if_ip_is_reachable_via_https(ip=du_init_config.oam_http_connection_details.addr,
                                               timeout=timeout)

    def _connect_to_cu(self):
        log_info(f'Connecting to Cloud BTS with IP: {self._ip}', to_console=True)
        try:
            self._api_cu.connect_to(host=self._ip,
                                    port=str(self._port),
                                    username=self._user_name,
                                    password=self._password,
                                    secure=True,
                                    alias=self._api_cu_alias)
        except AuthenticationFailedCu:
            log_debug(f"Login with {self._password} password to Cloud BTS CU with IP: {self._ip} has failed. "
                      f"Retrying with default password for uncommissioned CU: {self._password_when_uncommissioned}")
            sleep(1)  # Account lock for 1 sec due to failed login attempt
            self._api_cu.connect_to(host=self._ip,
                                    port=str(self._port),
                                    username=self._user_name,
                                    password=self._password_when_uncommissioned,
                                    secure=True,
                                    alias=self._api_cu_alias)

    def _connect_to_du(self, du_id, du_http):
        api_du_alias = f'{self._api_cu_alias}:DU{du_id}'
        log_debug(f'Connecting to DU{du_id} with IP: {du_http.addr}')
        try:
            self._api_du.connect_to(host=du_http.addr,
                                    port=du_http.port,
                                    username=du_http.username,
                                    password=du_http.password,
                                    secure=True,
                                    connection_name=api_du_alias)
        except AuthenticationFailedDu:
            log_debug(f"Login with {du_http.password} password to Cloud BTS DU with IP: {du_http.addr} has failed. "
                      f"Retrying with default password for uncommissioned DU: {self._password_when_uncommissioned}")
            sleep(1)  # Account lock for 1 sec due to failed login attempt
            self._api_du.connect_to(host=du_http.addr,
                                    port=du_http.port,
                                    username=du_http.username,
                                    password=self._password_when_uncommissioned,
                                    secure=True,
                                    connection_name=api_du_alias)
        self._api_du_aliases[str(du_id)] = api_du_alias

    def _get_node(self):
        if not self.cells:
            return None
        elif any([cell.rat == 'NR' for cell in self.cells]):
            return 'gNB'
        else:
            return 'eNB'
